-- Phase 66: secure Co-Marketing admin panel backend.
create or replace function public.comarketing_panel_data(_org uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid(); me jsonb; av jsonb; ps jsonb; city text; begin if u is null or (not public.usuario_dono_org(_org,u) and not public.eh_super_admin(u)) then return jsonb_build_object('ok',false,'reason','forbidden'); end if; select jsonb_build_object('id',id,'name',name,'slug',slug,'cidade',cidade,'categoria',coalesce(categoria,'outro'),'logo_url',logo_url),cidade into me,city from public.organizations where id=_org; if me is null then return jsonb_build_object('ok',false,'reason','org_not_found'); end if; select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'slug',slug,'cidade',cidade,'categoria',coalesce(categoria,'outro'),'logo_url',logo_url) order by name),'[]'::jsonb) into av from public.organizations where id<>_org and coalesce(ativo,true)=true and (city is null or lower(coalesce(cidade,''))=lower(city)); select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'org_origem',p.org_origem,'org_parceira',p.org_parceira,'status',p.status,'min_order_value',p.min_order_value,'discount_percent',p.discount_percent,'habilitada_origem',p.habilitada_origem,'habilitada_parceira',p.habilitada_parceira,'org_origem_name',a.name,'org_parceira_name',b.name) order by p.updated_at desc),'[]'::jsonb) into ps from public.parcerias p join public.organizations a on a.id=p.org_origem join public.organizations b on b.id=p.org_parceira where p.org_origem=_org or p.org_parceira=_org; return jsonb_build_object('ok',true,'organization',me,'available',av,'parcerias',ps); end$$;
create or replace function public.comarketing_update_identity(_org uuid,_cidade text,_categoria text,_logo_url text) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid(); begin if u is null or (not public.usuario_dono_org(_org,u) and not public.eh_super_admin(u)) then return jsonb_build_object('ok',false,'reason','forbidden'); end if; update public.organizations set cidade=nullif(btrim(_cidade),''),categoria=coalesce(nullif(btrim(_categoria),''),'outro'),logo_url=nullif(btrim(_logo_url),'') where id=_org; if not found then return jsonb_build_object('ok',false,'reason','org_not_found'); end if; return jsonb_build_object('ok',true); end$$;
revoke all on function public.comarketing_panel_data(uuid),public.comarketing_update_identity(uuid,text,text,text) from public,anon;
grant execute on function public.comarketing_panel_data(uuid),public.comarketing_update_identity(uuid,text,text,text) to authenticated;
